    out["id"]=[r[:] for r in w]
    out["rot180"]=[r[::-1] for r in w[::-1]]
    out["rot90"]=[list(r) for r in zip(*w)][::-1]
    out["rot270"]=[list(r) for r in zip(*w[::-1])]
    out["mirrorH"]=[r[::-1] for r in w]
    out["mirrorV"]=w[::-1]
    out["transpose"]=[list(r) for r in zip(*w)]
    out["antiT"]=[r[::-1] for r in zip(*w)][::-1]
    return out
